function Todos() {
  const [todos, setTodos] = useState([{ id: 1, t: 'a', done: false }, { id: 2, t: 'b', done: false }]);
  const toggle = (id) => setTodos((a) => a.map((x) => (x.id === id ? { ...x, done: !x.done } : x)));
  return <ul>{todos.map((x) => <li key={x.id} className={x.done ? 'done' : ''} onClick={() => toggle(x.id)}>{x.t}</li>)}</ul>;
}

