labs.solution:
function Name() {
  const [v, setV] = useState('');
  return <div><input value={v} onChange={(e) => setV(e.target.value)} /><p>Salom, {v}</p></div>;
}

function Agree() {
  const [ok, setOk] = useState(false);
  return <div><input type="checkbox" checked={ok} onChange={(e) => setOk(e.target.checked)} /><button disabled={!ok}>Davom</button></div>;
}

function Add({ onAdd }) {
  const [v, setV] = useState('');
  const submit = (e) => {
    e.preventDefault();
    if (!v.trim()) return;
    onAdd(v.trim());
    setV('');
  };
  return <form onSubmit={submit}><input value={v} onChange={(e) => setV(e.target.value)} /><button>+</button></form>;
}

function Login({ onLogin }) {
  const submit = (e) => {
    e.preventDefault();
    const d = new FormData(e.target);
    onLogin({ email: d.get('email'), pass: d.get('pass') });
  };
  return <form onSubmit={submit}><input name="email" /><input name="pass" type="password" /><button>Kirish</button></form>;
}

function City() {
  const [c, setC] = useState('toshkent');
  return <div><select value={c} onChange={(e) => setC(e.target.value)}><option value="toshkent">Toshkent</option><option value="buxoro">Buxoro</option></select><p>{c}</p></div>;
}

function Profile() {
