labs.solution:
function useQuery(url) {
  const [state, setState] = useState({ status: 'pending', data: null });
  useEffect(() => {
    let ignore = false;
    fetch(url)
      .then((r) => { if (!r.ok) throw new Error(); return r.json(); })
      .then((data) => { if (!ignore) setState({ status: 'success', data }); })
      .catch(() => { if (!ignore) setState({ status: 'error', data: null }); });
    return () => { ignore = true; };
  }, [url]);
  return state;
}

