function createStore(initial) {
  let state = initial;
  const subs = new Set();
  return {
    getState: () => state,
    setState: (fn) => { const next = fn(state); if (next !== state) { state = next; subs.forEach((s) => s()); } },
    subscribe: (s) => { subs.add(s); return () => subs.delete(s); },
  };
}

