labs.solution:
function cartSlice(state = { items: [] }, action) {
  switch (action.type) {
    case 'cart/added': return { ...state, items: [...state.items, action.payload] };
    case 'cart/removed': return { ...state, items: state.items.filter((i) => i.id !== action.payload) };
    default: return state;
  }
}

function makeStore(reducer) {
  let state = reducer(undefined, { type: '@@init' });
  return {
    getState: () => state,
    dispatch: (action) => { state = reducer(state, action); return action; },
  };
}

