labs.solution:
function useAction(fn) {
  const [pending, setPending] = useState(false);
  const run = async () => {
    setPending(true);
    try { await fn(); } finally { setPending(false); }
  };
  return [run, pending];
}

function useMyActionState(action, initial) {
  const [state, setState] = useState(initial);
  const queue = useRef(Promise.resolve(initial));
  const dispatch = (payload) => {
    queue.current = queue.current
      .then((prev) => action(prev, payload))
      .then((next) => { setState(next); return next; });
  };
  return [state, dispatch];
}

function Form({ save }) {
  const [state, setState] = useState({ pending: false, error: null });
  const submit = async (e) => {
    e.preventDefault();
    const name = new FormData(e.target).get('name');
    setState({ pending: true, error: null });
    const error = await save(name);
    setState({ pending: false, error: error ?? null });
  };
  return <form onSubmit={submit}><input name="name" /><button disabled={state.pending}>ok</button>{state.error && <p className="error">{state.error}</p>}</form>;
}

