  const [n, dispatch] = useReducer((s) => s + 1, 0);
  return [n, dispatch];
}

labs.solution:
const defaultReducer = (s) => s + 1;
function useCounter({ reducer = defaultReducer } = {}) {
  return useReducer(reducer, 0);
}

