labs.solution:
function UserList({ users }) {
  return <ul>{users.map((u) => <li key={u.id}>{u.name}</li>)}</ul>;
}
function UsersContainer() {
  const [users, setUsers] = useState([]);
  useEffect(() => { fetch('/api/users').then((r) => r.json()).then(setUsers); }, []);
  return <UserList users={users} />;
}

function Todo() {
  const [items, setItems] = useState([]);
  const [v, setV] = useState('');
  const add = (e) => {
    e.preventDefault();
    if (!v) return;
    setItems((a) => [...a, { id: Date.now() + a.length, v }]);
    setV('');
  };
  return <div><form onSubmit={add}><input value={v} onChange={(e) => setV(e.target.value)} /><button>+</button></form><ul>{items.map((t) => <li key={t.id} onClick={() => setItems((a) => a.filter((x) => x.id !== t.id))}>{t.v}</li>)}</ul></div>;
}

function Directory() {
  const [users, setUsers] = useState([]);
  const [q, setQ] = useState('');
  useEffect(() => { fetch('/api/users').then((r) => r.json()).then(setUsers); }, []);
  const shown = users.filter((u) => u.name.toLowerCase().includes(q.toLowerCase()));
  return <div><input value={q} onChange={(e) => setQ(e.target.value)} /><ul>{shown.map((u) => <li key={u.id}>{u.name}</li>)}</ul></div>;
}

function Countdown({ from }) {
  const [n, setN] = useState(from);
  useEffect(() => {
    if (n === 0) return;
    const id = setTimeout(() => setN(n - 1), 10);
    return () => clearTimeout(id);
  }, [n]);
  return <p>{n === 0 ? 'tamom' : n}</p>;
}

function Shop() {
  const [cart, setCart] = useState({});
  const total = PRODUCTS.reduce((s, p) => s + p.price * (cart[p.id] ?? 0), 0);
  return <div><ul>{PRODUCTS.map((p) => <li key={p.id}>{p.name}<button onClick={() => setCart((c) => ({ ...c, [p.id]: (c[p.id] ?? 0) + 1 }))}>+</button></li>)}</ul><p className="total">{total}</p></div>;
}

function List() {
  return <ul>{POSTS.map((p) => <li key={p.id}><Link to={`/posts/${p.id}`}>{p.title}</Link></li>)}</ul>;
}
function Post() {
  const { id } = useParams();
  return <h1>{POSTS.find((p) => p.id === Number(id))?.title}</h1>;
}
function App() {
  return <Routes><Route path="/" element={<List />} /><Route path="/posts/:id" element={<Post />} /></Routes>;
}

labs.starter:
function ThemeProvider({ children }) {
  return null;
}
function useTheme() {}

labs.solution:
const ThemeCtx = createContext(null);
function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light');
  const value = useMemo(() => ({ theme, toggle: () => setTheme((t) => (t === 'light' ? 'dark' : 'light')) }), [theme]);
  return <ThemeCtx.Provider value={value}>{children}</ThemeCtx.Provider>;
}
function useTheme() {
  return useContext(ThemeCtx);
}

