function Wizard() {
  const [step, setStep] = useState(1);
  const [name, setName] = useState('');
  if (step === 1) {
    return <div><input value={name} onChange={(e) => setName(e.target.value)} /><button disabled={!name} onClick={() => setStep(2)}>Keyingi</button></div>;
  }
  return <div><p>Salom, {name}</p><button onClick={() => setStep(1)}>Orqaga</button></div>;
}
